// A chaining hash map: djb2 string hash, one array of buckets,
// each bucket a list of [key, value] pairs.
class HashMap {
  constructor(bucketCount = 16) {
    this.buckets = Array.from({ length: bucketCount }, () => []);
    this.size = 0;
  }
  bucketIndex(key) {
    const s = String(key);
    let h = 5381;
    for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
    return h % this.buckets.length;
  }
  set(key, value) {
    const bucket = this.buckets[this.bucketIndex(key)];
    const hit = bucket.find(e => e[0] === key);
    if (hit) hit[1] = value;
    else { bucket.push([key, value]); this.size++; }
    return this;
  }
  get(key, fallback) {
    const hit = this.buckets[this.bucketIndex(key)].find(e => e[0] === key);
    return hit ? hit[1] : fallback;
  }
  delete(key) {
    const bucket = this.buckets[this.bucketIndex(key)];
    const i = bucket.findIndex(e => e[0] === key);
    if (i === -1) return false;
    bucket.splice(i, 1);
    this.size--;
    return true;
  }
}

const prices = new HashMap(8);
prices.set('apple', 0.4).set('banana', 0.25).set('cherry', 3.5).set('date', 2.1);
console.log('banana costs', prices.get('banana'));
console.log('missing key ->', prices.get('kiwi', 'not stocked'));

prices.set('banana', 0.3); // update in place
console.log('banana now costs', prices.get('banana'));

prices.delete('date');
console.log('after delete, size =', prices.size);

// Peek inside: which bucket did each key land in?
prices.buckets.forEach((b, i) => {
  if (b.length) console.log('bucket ' + i + ':', b.map(e => e[0]).join(', '));
});

nb.set('hashmap_size', prices.size);

// Fixed 64 buckets, insert 256 keys, sample as the load factor climbs.
const map = new HashMap64();

function HashMap64() {
  const m = Object.create(null);
  m.buckets = Array.from({ length: 64 }, () => []);
  m.size = 0;
  m.set = (key) => {
    const s = String(key);
    let h = 5381;
    for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
    m.buckets[h % 64].push([key, true]);
    m.size++;
  };
  return m;
}

const rows = [];
for (let i = 1; i <= 256; i++) {
  map.set('user:' + (i * 7919)); // spread the key space a little
  if (i % 8 === 0) {
    const alpha = map.size / 64;
    // probe length for entry j in a chain is j+1; average over all entries
    let probeSum = 0, maxChain = 0;
    for (const b of map.buckets) {
      maxChain = Math.max(maxChain, b.length);
      for (let j = 0; j < b.length; j++) probeSum += j + 1;
    }
    rows.push({ alpha, value: probeSum / map.size, series: 'measured avg probes' });
    rows.push({ alpha, value: 1 + alpha / 2, series: 'theory 1 + a/2' });
    rows.push({ alpha, value: maxChain, series: 'longest chain' });
  }
}
console.log('final load factor:', map.size / 64);

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 300,
  title: 'Probe length vs load factor (64 buckets, chaining)',
  data: { values: rows },
  mark: { type: 'line', point: true },
  encoding: {
    x: { field: 'alpha', type: 'quantitative', title: 'load factor a' },
    y: { field: 'value', type: 'quantitative', title: 'probes / chain length' },
    color: { field: 'series', type: 'nominal', title: null },
  },
};
